const _astro_dataLayerContent = [["Map",1,2,9,10,57,58],"meta::meta",["Map",3,4,5,6,7,8],"astro-version","5.15.2","content-config-digest","de65a349ecb346e3","astro-config-digest","{\"root\":{},\"srcDir\":{},\"publicDir\":{},\"outDir\":{},\"cacheDir\":{},\"site\":\"https://atelierdp.github.io\",\"compressHTML\":true,\"base\":\"/\",\"trailingSlash\":\"ignore\",\"output\":\"static\",\"scopedStyleStrategy\":\"attribute\",\"build\":{\"format\":\"directory\",\"client\":{},\"server\":{},\"assets\":\"_astro\",\"serverEntry\":\"entry.mjs\",\"redirects\":true,\"inlineStylesheets\":\"auto\",\"concurrency\":1},\"server\":{\"open\":false,\"host\":false,\"port\":4321,\"streaming\":true,\"allowedHosts\":[]},\"redirects\":{},\"image\":{\"endpoint\":{\"route\":\"/_image\"},\"service\":{\"entrypoint\":\"astro/assets/services/sharp\",\"config\":{}},\"domains\":[],\"remotePatterns\":[],\"responsiveStyles\":false},\"devToolbar\":{\"enabled\":true},\"markdown\":{\"syntaxHighlight\":{\"type\":\"shiki\",\"excludeLangs\":[\"math\"]},\"shikiConfig\":{\"langs\":[],\"langAlias\":{},\"theme\":\"github-dark\",\"themes\":{},\"wrap\":false,\"transformers\":[]},\"remarkPlugins\":[],\"rehypePlugins\":[],\"remarkRehype\":{},\"gfm\":true,\"smartypants\":true},\"security\":{\"checkOrigin\":true,\"allowedDomains\":[]},\"env\":{\"schema\":{},\"validateSecrets\":false},\"experimental\":{\"clientPrerender\":false,\"contentIntellisense\":false,\"headingIdCompat\":false,\"preserveScriptOrder\":false,\"liveContentCollections\":false,\"csp\":false,\"staticImportMetaEnv\":false,\"chromeDevtoolsWorkspace\":false,\"failOnPrerenderConflict\":false},\"legacy\":{\"collections\":false}}","posts",["Map",11,12,35,36],"hello-world-copy",{id:11,data:13,body:19,filePath:20,digest:21,rendered:22},{title:14,slug:11,publishDate:15,description:16,tags:17},"basic page",["Date","2025-10-16T00:00:00.000Z"],"My second post",[18],"astro","De volledige tekst","content/blog/hello-world copy.md","9a6bf550ffddc3d4",{html:23,metadata:24},"<p>De volledige tekst</p>",{headings:25,localImagePaths:26,remoteImagePaths:27,frontmatter:28,imagePaths:34},[],[],[],{title:14,date:29,excerpt:30,tags:31,cover:32,slug:11,description:16,publishDate:33},["Date","2024-02-02T00:00:00.000Z"],"Waarom een hele tekst geven als het ook met minder kan?",[18],"./astro-tw.png",["Date","2025-10-16T00:00:00.000Z"],[],"hello-world",{id:35,data:37,body:42,filePath:43,digest:44,rendered:45},{title:38,slug:35,publishDate:39,description:40,tags:41},"How to build a static lightweight MDX blog with Astro and Tailwind CSS: Step-by-step guide",["Date","2025-10-15T00:00:00.000Z"],"My first post",[18],"Hey! My first blog post is here.","content/blog/hello-world.md","4e263cbec07e7b1f",{html:46,metadata:47},"<p>Hey! My first blog post is here.</p>",{headings:48,localImagePaths:49,remoteImagePaths:50,frontmatter:51,imagePaths:56},[],[],[],{title:38,date:52,excerpt:53,tags:54,cover:32,slug:35,description:40,publishDate:55},["Date","2024-02-02T00:00:00.000Z"],"A full, step-by-step guide for developers seeking to implement a portfolio or blog publication with Astro.",[18],["Date","2025-10-15T00:00:00.000Z"],[],"recepten",["Map",59,60,89,90],"ragout-hert-ovenaardappel",{id:59,data:61,body:68,filePath:69,digest:70,rendered:71},{title:62,slug:59,publishDate:63,description:62,excerpt:64,tags:65},"Ragout van hert met ovenaardappel",["Date","2025-10-21T00:00:00.000Z"],"Comfortfood voor een herfstdag",[66,67],"hoofdgerecht","wild","# Ingrediënten\r\n- 6kg hertenragout\r\n- 2kg ajuin\r\n- 200g suiker\r\n- 7 lepels bloem\r\n- 2 flessen rode wijn\r\n- Tijm\r\n- Laurier\r\n- Peterselie\r\n- Jeneverbessen & kruidnagel\r\n- Peper & zout\r\n- Veenbessenkonfituur (of rode bessenconfituur)\r\n- 25 aardappels (1 pp)\r\n- 4 rode uien\r\n- 1kg boschampignons (of kastanjechampignons)\r\n- Boter\r\n- Eventueel look\r\n\r\n\r\n# Recept\r\n\r\nMaak de ajuin schoon en versnij fijn. Warm de wijn op in een kookpot. Stoof aan in een grote kom. Doe dit eventueel in meerdere keren na elkaar zodat de ajuin goed kan stoven. Haal uit de pan, voeg wat extra vetstof toe en korst het vlees aan. Ook hier: indien te veel voor je pan, best in enkele keren doen. Kruid met peper terwijl het vlees korst. Voeg de ui opnieuw toe en strooi de bloem er over. Roer goed om en laat even meestoven. Blus het geheel met de rode wijn en roer de aanbaksels goed los. Kneus de jeneverbessen en doe ze samen met enkele kruidnagels in de saus. Laat het geheel goed sudderen tot 2u. Langer mag zeker, korter indien nodig.\r\n\r\nWas de aardappels goed, wrijf ze droog en snij inkepingen om de 2-3 mm van boven (zoals de aardappel normaal ligt) tot net niet helemaal door. Daardoor blijft alles aan elkaar hangen, maar heb je wel een mooi effect. Steek in elke aardappel ergens tussen 2 laagjes een blaadje laurier. Leg de aardappels op een bakplaat (met bakpapier of bakmat), overgiet met een beetje olijfolie en kruid elke aardappel met peper en zout. Zet in de oven op 200°C gedurende +/- 50 minuten.\r\n\r\nWas de veldsla en verwijder indien nodig de minder mooie blaadjes. Dep ze goed af. Reinig de rode ui, snij in (halve) ringen. Versnijd de champignons in kwartjes en bak ze in een hete pan met boter. Kruid ze af met peper. Maak een dressing met arachideolie en witte wijnazijn, peper, zout en wat mosterd. Meng de 3 ingrediënten bij elkaar en meng de dressing erbij.","content/recepten/ragout-van-hert-met-ovenaardappel.md","14e38c888f900416",{html:72,metadata:73},"<h1 id=\"ingrediënten\">Ingrediënten</h1>\n<ul>\n<li>6kg hertenragout</li>\n<li>2kg ajuin</li>\n<li>200g suiker</li>\n<li>7 lepels bloem</li>\n<li>2 flessen rode wijn</li>\n<li>Tijm</li>\n<li>Laurier</li>\n<li>Peterselie</li>\n<li>Jeneverbessen &#x26; kruidnagel</li>\n<li>Peper &#x26; zout</li>\n<li>Veenbessenkonfituur (of rode bessenconfituur)</li>\n<li>25 aardappels (1 pp)</li>\n<li>4 rode uien</li>\n<li>1kg boschampignons (of kastanjechampignons)</li>\n<li>Boter</li>\n<li>Eventueel look</li>\n</ul>\n<h1 id=\"recept\">Recept</h1>\n<p>Maak de ajuin schoon en versnij fijn. Warm de wijn op in een kookpot. Stoof aan in een grote kom. Doe dit eventueel in meerdere keren na elkaar zodat de ajuin goed kan stoven. Haal uit de pan, voeg wat extra vetstof toe en korst het vlees aan. Ook hier: indien te veel voor je pan, best in enkele keren doen. Kruid met peper terwijl het vlees korst. Voeg de ui opnieuw toe en strooi de bloem er over. Roer goed om en laat even meestoven. Blus het geheel met de rode wijn en roer de aanbaksels goed los. Kneus de jeneverbessen en doe ze samen met enkele kruidnagels in de saus. Laat het geheel goed sudderen tot 2u. Langer mag zeker, korter indien nodig.</p>\n<p>Was de aardappels goed, wrijf ze droog en snij inkepingen om de 2-3 mm van boven (zoals de aardappel normaal ligt) tot net niet helemaal door. Daardoor blijft alles aan elkaar hangen, maar heb je wel een mooi effect. Steek in elke aardappel ergens tussen 2 laagjes een blaadje laurier. Leg de aardappels op een bakplaat (met bakpapier of bakmat), overgiet met een beetje olijfolie en kruid elke aardappel met peper en zout. Zet in de oven op 200°C gedurende +/- 50 minuten.</p>\n<p>Was de veldsla en verwijder indien nodig de minder mooie blaadjes. Dep ze goed af. Reinig de rode ui, snij in (halve) ringen. Versnijd de champignons in kwartjes en bak ze in een hete pan met boter. Kruid ze af met peper. Maak een dressing met arachideolie en witte wijnazijn, peper, zout en wat mosterd. Meng de 3 ingrediënten bij elkaar en meng de dressing erbij.</p>",{headings:74,localImagePaths:82,remoteImagePaths:83,frontmatter:84,imagePaths:88},[75,79],{depth:76,slug:77,text:78},1,"ingrediënten","Ingrediënten",{depth:76,slug:80,text:81},"recept","Recept",[],[],{title:62,date:85,excerpt:64,tags:86,cover:32,slug:59,description:62,type:80,publishDate:87},["Date","2025-10-21T00:00:00.000Z"],[66,67],["Date","2025-10-21T00:00:00.000Z"],[],"noorse-viskoekjes",{id:89,data:91,body:98,filePath:99,digest:100,rendered:101},{title:92,slug:89,publishDate:93,description:92,excerpt:94,tags:95},"Noorse Viskoekjes",["Date","2025-10-21T00:00:00.000Z"],"Een Noorse lekkernij voor elke dag - een bordje viskoekjes met een heerlijke wortelpuree",[96,97],"voorgerecht","vis","# Ingrediënten\r\n- 2kg Koolvis (bvb Alaska Pollak) of een andere stevige vis\r\n- 5 tl zout\r\n- 5dl culinaire room\r\n- 5dl melk\r\n- Extra melk voor de puree\r\n- 5 el aardappelzetmeel\r\n- Nootmuskaat\r\n- Peper\r\n- Boter\r\n- 1,3kg aardappelen (loskokend)\r\n- 1kg wortelen\r\n- 4 citroenen\r\n- abrikozenconfituur\r\n- Evt wat groene kruiden (dille of peterselie)\r\n\r\n# Recept\r\n\r\nSchil en snij de aardappels en wortelen in niet al te grove stukken en kook ze tot ze zacht genoeg zijn om een grove puree van te maken. Stamp alles en meng met wat melk en vetstof. Breng op smaak met peper en zout.\r\n\r\nSnij de vis in blokjes van 2-3 cm. Doe de vis en het zout in een foodprocessor gedurende +/- 1 min. Indien te veel: doe dit in meerdere keren. Doe bij de vis peper, muskaatnoot en wat van het aardappelzetmeel en wat melk zodat het makkelijker vermengt.\r\n\r\nDoe alles uit de foodprocessor, voeg alle resterende ingrediënten erbij en roer goed tot een stevige massa.\r\n\r\nSmelt wat boter in een pan, schep met een soeplepel van de visbrij (ter grootte van een bolletje ijs) en bak in de pan. Duw het gerust wat platter zoals een hamburger. Bak goudbruin aan beide zijden en houd warm.  \r\n\r\nServeer met de puree en een schijfje citroen en een klein takje groene kruiden","content/recepten/noorse-viskoekjes.md","0c408282e132e105",{html:102,metadata:103},"<h1 id=\"ingrediënten\">Ingrediënten</h1>\n<ul>\n<li>2kg Koolvis (bvb Alaska Pollak) of een andere stevige vis</li>\n<li>5 tl zout</li>\n<li>5dl culinaire room</li>\n<li>5dl melk</li>\n<li>Extra melk voor de puree</li>\n<li>5 el aardappelzetmeel</li>\n<li>Nootmuskaat</li>\n<li>Peper</li>\n<li>Boter</li>\n<li>1,3kg aardappelen (loskokend)</li>\n<li>1kg wortelen</li>\n<li>4 citroenen</li>\n<li>abrikozenconfituur</li>\n<li>Evt wat groene kruiden (dille of peterselie)</li>\n</ul>\n<h1 id=\"recept\">Recept</h1>\n<p>Schil en snij de aardappels en wortelen in niet al te grove stukken en kook ze tot ze zacht genoeg zijn om een grove puree van te maken. Stamp alles en meng met wat melk en vetstof. Breng op smaak met peper en zout.</p>\n<p>Snij de vis in blokjes van 2-3 cm. Doe de vis en het zout in een foodprocessor gedurende +/- 1 min. Indien te veel: doe dit in meerdere keren. Doe bij de vis peper, muskaatnoot en wat van het aardappelzetmeel en wat melk zodat het makkelijker vermengt.</p>\n<p>Doe alles uit de foodprocessor, voeg alle resterende ingrediënten erbij en roer goed tot een stevige massa.</p>\n<p>Smelt wat boter in een pan, schep met een soeplepel van de visbrij (ter grootte van een bolletje ijs) en bak in de pan. Duw het gerust wat platter zoals een hamburger. Bak goudbruin aan beide zijden en houd warm.</p>\n<p>Serveer met de puree en een schijfje citroen en een klein takje groene kruiden</p>",{headings:104,localImagePaths:107,remoteImagePaths:108,frontmatter:109,imagePaths:113},[105,106],{depth:76,slug:77,text:78},{depth:76,slug:80,text:81},[],[],{title:92,date:110,excerpt:94,tags:111,cover:32,slug:89,description:92,type:80,publishDate:112},["Date","2025-10-21T00:00:00.000Z"],[96,97],["Date","2025-10-21T00:00:00.000Z"],[]];

